import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.2Gs1zKBA.js";const b=JSON.parse('{"title":"TCP与末端工具","description":"","frontmatter":{},"headers":[],"relativePath":"use-cases/tcp-tools.md","filePath":"use-cases/tcp-tools.md","lastUpdated":1794559243000}'),i={name:"use-cases/tcp-tools.md"};function l(o,t,n,c,r,p){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="tcp与末端工具" tabindex="-1">TCP与末端工具 <a class="header-anchor" href="#tcp与末端工具" aria-label="Permalink to &quot;TCP与末端工具&quot;">​</a></h1><p>本案例设置法兰到夹爪尖端的几何变换，并让 TCP 沿基座坐标系 <code>+X</code> 移动 2 cm，用于验证笛卡尔运动是否以实际工具作用点为参考。</p><div class="danger custom-block"><p class="custom-block-title">真机操作提示</p><p>错误的安装方向、TCP 或负载参数会使工具实际路径偏离预期。运行前必须测量法兰到工具作用点的真实位姿，固定工具和线缆，清空完整运动空间，并确保紧急停止可用。示例结束时会失能机械臂；失能前必须可靠支撑机械臂及工具。</p></div><h2 id="演示目标" tabindex="-1">演示目标 <a class="header-anchor" href="#演示目标" aria-label="Permalink to &quot;演示目标&quot;">​</a></h2><p>示例依次完成以下流程：</p><ol><li>进入非奇异演示姿态；</li><li>调用 <code>set_tcp()</code> 设置法兰局部 <code>+Z</code> 方向 17 cm 的 TCP；</li><li>在机械臂不动的情况下读取法兰与 TCP 位姿，验证两参考点相距 170 mm；</li><li>保持末端姿态，让 TCP 沿基座坐标系 <code>+X</code> 移动 2 cm；</li><li>展示常见工具的 TCP 参数格式；</li><li>调用 <code>clear_tcp()</code> 恢复以法兰面为参考。</li></ol><p>示例中的 17 cm 只用于当前工具，不能替代对实际工具的测量。<code>set_tcp()</code> 本身不会让机械臂运动，只改变 <code>get_pose()</code> 和后续笛卡尔运动使用的几何参考点。</p><h2 id="安装与准备" tabindex="-1">安装与准备 <a class="header-anchor" href="#安装与准备" aria-label="Permalink to &quot;安装与准备&quot;">​</a></h2><p>进入 <code>onero-sdk</code> 仓库并安装逆运动学、动力学依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/woan/workspace/onero-sdk</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.[ik,dynamics]&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>真机运行前还需要完成 <a href="/onerobot-A1/getting-started/hardware">CAN 接口配置与连接检查</a>，并确认：</p><ul><li><code>can0</code> 连接 A1R 右臂，实体安装方式为 <code>humanoid_right</code>；</li><li>法兰中心到夹爪作用点沿法兰局部 <code>+Z</code> 的实测距离为 170 mm；</li><li>工具、工件和线缆已可靠固定，完整扫掠路径无障碍；</li><li>急停可用，机械臂失能前有人或支架可靠承托；</li><li>已按实测值配置工具与工件的总质量和合成重心；TCP 不会自动设置负载。</li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数或设置</th><th>示例值</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>A1R</code></td><td>右臂运动学模型</td></tr><tr><td><code>channel</code></td><td><code>can0</code></td><td>真机 SocketCAN 通道</td></tr><tr><td><code>mounting</code></td><td><code>humanoid_right</code></td><td>A1R 右肩竖直安装及重力方向</td></tr><tr><td><code>with_gripper</code></td><td><code>True</code></td><td>使用夹爪重力补偿档位</td></tr><tr><td>TCP 偏移</td><td><code>[0, 0, 0.17] m</code></td><td>法兰局部 <code>+Z</code> 到夹爪尖端</td></tr><tr><td>目标增量</td><td><code>[+0.02, 0, 0] m</code></td><td>基座坐标系 <code>+X</code> 方向移动 2 cm</td></tr><tr><td>目标姿态</td><td>保持起始姿态</td><td>避免额外姿态翻转</td></tr><tr><td>运动时间</td><td><code>4.0 s</code></td><td>运动后等待 1 s 并刷新反馈</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">基座 +X，不是工具 +Z</p><p>当前示例没有传入 <code>frame=&quot;tool&quot;</code>。目标由当前 TCP 位置加 <code>[0.02, 0, 0]</code> 得到，因此执行的是基座坐标系 <code>+X</code> 方向的运动。</p></div><h2 id="操作阶段" tabindex="-1">操作阶段 <a class="header-anchor" href="#操作阶段" aria-label="Permalink to &quot;操作阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>接口或阶段</th><th>操作含义</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>movej()</code></td><td>进入非奇异 IK 演示姿态</td></tr><tr><td style="text-align:right;">2</td><td><code>clear_tcp()</code> + <code>get_pose()</code></td><td>读取法兰位姿</td></tr><tr><td style="text-align:right;">3</td><td><code>set_tcp([0, 0, 0.17])</code></td><td>注册夹爪尖端相对法兰的偏移</td></tr><tr><td style="text-align:right;">4</td><td><code>get_pose()</code></td><td>读取 TCP 位姿并校验 170 mm 偏移</td></tr><tr><td style="text-align:right;">5</td><td><code>movel()</code></td><td>保持姿态，让 TCP 沿 base <code>+X</code> 移动 2 cm</td></tr><tr><td style="text-align:right;">6</td><td><code>get_state()</code> + <code>get_pose()</code></td><td>刷新反馈并计算实际位移和终点误差</td></tr><tr><td style="text-align:right;">7</td><td><code>clear_tcp()</code></td><td>恢复法兰参考</td></tr><tr><td style="text-align:right;">8</td><td><code>disable()</code></td><td>撤销电机保持力矩</td></tr></tbody></table><h2 id="真机运行" tabindex="-1">真机运行 <a class="header-anchor" href="#真机运行" aria-label="Permalink to &quot;真机运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/woan/workspace/onero-sdk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.venv/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/11_tool_frame.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/11_tool_frame.py" target="_blank" rel="noreferrer">查看完整源码</a></p><p>关键终端信息包括：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP 设置完成: position=[0, 0, 0.17]</span></span>
<span class="line"><span>两参考点距离: 170.0 mm</span></span>
<span class="line"><span>变换计算误差: &lt;接近 0&gt; mm</span></span>
<span class="line"><span>让夹爪尖端沿 base +X 平移 2cm，到达 [...]</span></span>
<span class="line"><span>TCP 实际位移: [...] mm</span></span>
<span class="line"><span>TCP 目标误差: ... mm</span></span>
<span class="line"><span>TCP 已重置，运动指令以法兰面为参考</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="结果判断" tabindex="-1">结果判断 <a class="header-anchor" href="#结果判断" aria-label="Permalink to &quot;结果判断&quot;">​</a></h2><p>运行成功应同时满足：</p><ul><li>型号、CAN 通道、安装方向和实际工具尺寸与源码配置一致；</li><li>设置 TCP 前后机械臂没有运动，法兰与 TCP 的距离为 170 mm；</li><li>TCP 理论位置与反馈位置一致，变换计算误差接近 0；</li><li>工具作用点沿基座 <code>+X</code> 方向移动约 2 cm，末端姿态保持连续；</li><li>反馈位姿与现场观察一致，没有 IK、限位或通信异常；</li><li>演示结束后 TCP 被清除，机械臂在得到可靠支撑后正常失能。</li></ul><p>终端反馈用于检查示例流程；没有独立测量数据时，不应据此声称笛卡尔绝对精度或重复定位精度。</p><h2 id="末端工具边界" tabindex="-1">末端工具边界 <a class="header-anchor" href="#末端工具边界" aria-label="Permalink to &quot;末端工具边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>负责内容</th><th>不会自动完成</th></tr></thead><tbody><tr><td><code>set_tcp()</code></td><td>工具作用点的位置和朝向</td><td>夹爪通信、负载质量和重心</td></tr><tr><td><code>with_gripper=True</code></td><td>选择夹爪重力补偿档位</td><td>根据实际质量建立 payload</td></tr><tr><td><code>end_effector</code></td><td>末端工具驱动与动作控制</td><td>TCP 和负载配置</td></tr><tr><td><code>set_payload()</code></td><td>工具与工件总质量和合成重心</td><td>工具几何和夹爪动作</td></tr></tbody></table><h2 id="中断与安全状态" tabindex="-1">中断与安全状态 <a class="header-anchor" href="#中断与安全状态" aria-label="Permalink to &quot;中断与安全状态&quot;">​</a></h2><p>程序在正常流程中调用 <code>clear_tcp()</code>；<code>finally</code> 中只调用 <code>disable()</code>。如果此前发生异常，不保证执行到清除 TCP 的步骤。<code>disable()</code> 会撤销保持力矩，必须先可靠支撑机械臂和工具。</p><p><code>clear_tcp()</code> 只改变后续运动使用的几何参考，既不会停止当前运动，也不会让电机失能。若工具方向异常、接近障碍物或出现失控趋势，应使用现场适用的紧急停止措施。</p><p>完整参数说明见<a href="/onerobot-A1/tools/">TCP、负载与末端工具</a>。</p><p><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/11_tool_frame.py" target="_blank" rel="noreferrer">查看完整源码</a></p>`,33)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
